            ["script"] = "local BlockPlayer = require \"actions/BlockPlayer\"\nlocal MessageBox = require \"actions/MessageBox\"\nlocal Animate = require \"actions/Animate\"\nlocal Do = require \"actions/Do\"\nlocal Serial = require \"actions/Serial\"\nlocal Parallel = require \"actions/Parallel\"\nlocal Ease = require \"actions/Ease\"\nlocal Wait = require \"actions/Wait\"\nlocal AudioFade = require \"actions/AudioFade\"\nlocal PlayAudio = require \"actions/PlayAudio\"\n\nreturn function(self)\n    walkout, walkin, sprites = self.scene.player:split(nil, true)\n    for k in pairs(GameState.party) do\n        sprites[k].x = self.scene.player.x - 60\n        sprites[k].y = self.scene.player.y - 60\n    end\n\n    return BlockPlayer {\n        walkout,\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(sprites.babyt.sprite, \"idleup\"),\n        Animate(sprites.tails.sprite, \"idleup\"),\n        Wait(1),\n\n        Parallel {\n            sprites.babyt:hop(),\n            MessageBox{message=\"Baby T: Whoah!... {p60}Is that like a grown-up Tails?...\"}\n        },\n        MessageBox{message=\"Tails: No way...\"},\n        Wait(1),\n        Parallel {\n            Ease(self.scene.objectLookup.EpochTails.sprite.color, 1, 255, 0.5),\n            Ease(self.scene.objectLookup.EpochTails.sprite.color, 2, 255, 0.5),\n            Ease(self.scene.objectLookup.EpochTails.sprite.color, 3, 255, 0.5)\n        },\n        MessageBox{message=\"Miles: The War Claws destroyed everything during the Great War...\"},\n        MessageBox{message=\"Miles: I was told that, after the King caught Mobotropolis' War Minister {h Julian Kintobor} plotting against\\nthe kingdom, he was banished...\"},\n        MessageBox{message=\"Miles: It was then that the now former War Minister made a deal with the {h War Claws}...\"},\n        MessageBox{message=\"Miles: The War Claws, however, rejected Julian's 'roboticization' plan. {p80}They thought it put too much trust\\nin the efficacy of mind control technology.\"},\n        MessageBox{message=\"Miles: After all, if they failed to curb free will, it would then mean thousands of angry, super strong, roboticized citizenry to deal with...\"},\n        MessageBox{message=\"Miles: So in exchange for his amnesty, Julian would instead build them a bomb. {p60}A very, {p60}very {p60}powerful bomb... {p80}to be used on Mobotropolis.\"},\n        Parallel { \n            sprites.tails:hop(),\n            MessageBox{message=\"Tails: What!? {p60}That's not how it happened!\"}\n        },\n        MessageBox{message=\"Miles: I wish that the King never learned of Julian's betrayal... {p60}Julian at least had the power to win the Great War for Mobotropolis.\"},\n        MessageBox{message=\"Miles: After that? {p60}Sure maybe most of us would be roboticized, but at least we'd have a chance. {p60}Maybe some of us could resist the mind control, like the War Claws feared...\"},\n        Parallel {\n            sprites.tails:hop(),\n            MessageBox{message=\"Tails: You wish that Robotnik took over?! {p60}That's what I'm trying to prevent!!\"}\n        },\n        Ease(self.scene.objectLookup.EpochTails.sprite.color, 4, 0, 0.5),\n        Animate(sprites.tails.sprite, \"saddown\"),\n        MessageBox{message=\"Tails: ...{p60}is this what happens if I get my wish?...\"},\n        Animate(sprites.babyt.sprite, \"idleleft\"),\n        MessageBox{message=\"Baby T: It's probably just another trial, Tails! {p60}Just testing our resolve, right?\"},\n        Animate(sprites.b.sprite, \"pose\"),\n        MessageBox{message=\"B: ...\"},\n        Do(function() self.scene.objectLookup.EpochTails:permanentRemove() end),\n\n        walkin\n    }\nend"
